package com.taskmate.dao;
import com.taskmate.database.Database; import com.taskmate.models.*; import java.sql.*; import java.time.*; import java.util.*;
public class TaskDao {
    public List<Task> tasks(User u) throws SQLException {
        String q="""
          SELECT t.id,t.title,c.course_name,t.task_type,t.due_date,t.priority,t.max_marks,
          COALESCE(s.status,'PENDING') status,s.marks,s.feedback,f.name faculty
          FROM tasks t JOIN courses c ON c.id=t.course_id JOIN users f ON f.id=t.faculty_id
          LEFT JOIN submissions s ON s.task_id=t.id AND s.student_id=?
          WHERE (?='HOD' OR (?='FACULTY' AND t.faculty_id=?) OR (?='STUDENT' AND EXISTS(SELECT 1 FROM enrollments e WHERE e.course_id=t.course_id AND e.student_id=?)))
          ORDER BY t.due_date,t.id""";
        try(Connection c=Database.connect();PreparedStatement s=c.prepareStatement(q)){s.setLong(1,u.id());s.setString(2,u.role());s.setString(3,u.role());s.setLong(4,u.id());s.setString(5,u.role());s.setLong(6,u.id());try(ResultSet r=s.executeQuery()){List<Task> out=new ArrayList<>();while(r.next()){java.sql.Date d=r.getDate("due_date");Object rawMarks=r.getObject("marks");Double marks=rawMarks==null?null:((Number)rawMarks).doubleValue();out.add(new Task(r.getLong("id"),r.getString("title"),r.getString("course_name"),r.getString("task_type"),d.toLocalDate(),r.getString("priority"),r.getDouble("max_marks"),r.getString("status"),marks,r.getString("feedback"),r.getString("faculty")));}return out;}}
    }
    public List<String[]> courses(User u) throws SQLException {
        String q="SELECT c.id,c.course_code,c.course_name,c.academic_year,c.section,f.name,(SELECT COUNT(*) FROM enrollments e WHERE e.course_id=c.id) students FROM courses c JOIN users f ON f.id=c.faculty_id WHERE ?='HOD' OR (?='FACULTY' AND c.faculty_id=?) OR (?='STUDENT' AND EXISTS(SELECT 1 FROM enrollments e WHERE e.course_id=c.id AND e.student_id=?)) ORDER BY c.course_code";
        try(Connection c=Database.connect();PreparedStatement s=c.prepareStatement(q)){s.setString(1,u.role());s.setString(2,u.role());s.setLong(3,u.id());s.setString(4,u.role());s.setLong(5,u.id());try(ResultSet r=s.executeQuery()){List<String[]> a=new ArrayList<>();while(r.next())a.add(new String[]{""+r.getLong(1),r.getString(2),r.getString(3),r.getString(4),r.getString(5),r.getString(6),""+r.getInt(7)});return a;}}
    }
    public List<String[]> submissionsForTask(User faculty,long taskId)throws SQLException{requireRole(faculty,"FACULTY");String q="SELECT s.id,u.name,s.status,s.marks FROM submissions s JOIN tasks t ON t.id=s.task_id JOIN users u ON u.id=s.student_id WHERE t.id=? AND t.faculty_id=? AND s.status IN ('SUBMITTED','EVALUATED') ORDER BY u.name";try(Connection c=Database.connect();PreparedStatement p=c.prepareStatement(q)){p.setLong(1,taskId);p.setLong(2,faculty.id());try(ResultSet r=p.executeQuery()){List<String[]> rows=new ArrayList<>();while(r.next())rows.add(new String[]{""+r.getLong(1),r.getString(2),r.getString(3),r.getString(4)});return rows;}}}
    public long count(String sql, User u) throws SQLException { try(Connection c=Database.connect();PreparedStatement s=c.prepareStatement(sql)){s.setLong(1,u.id());try(ResultSet r=s.executeQuery()){r.next();return r.getLong(1);}} }
    public void createTask(User faculty,long course,String title,String description,String type,LocalDate due,String priority,double marks) throws SQLException {
        requireRole(faculty,"FACULTY"); if(title.isBlank()||marks<=0||due==null)throw new IllegalArgumentException("Title, future deadline, and positive maximum marks are required.");
        String q="INSERT INTO tasks(course_id,faculty_id,title,description,task_type,due_date,priority,max_marks) SELECT c.id,?, ?, ?, ?, ?, ?, ? FROM courses c WHERE c.id=? AND c.faculty_id=?";
        try(Connection c=Database.connect()){c.setAutoCommit(false);try(PreparedStatement s=c.prepareStatement(q,Statement.RETURN_GENERATED_KEYS)){s.setLong(1,faculty.id());s.setString(2,title.trim());s.setString(3,description);s.setString(4,type);s.setDate(5,java.sql.Date.valueOf(due));s.setString(6,priority);s.setDouble(7,marks);s.setLong(8,course);s.setLong(9,faculty.id());if(s.executeUpdate()!=1)throw new SQLException("Course is not assigned to this faculty member.");long id;try(ResultSet k=s.getGeneratedKeys()){k.next();id=k.getLong(1);}try(PreparedStatement p=c.prepareStatement("INSERT INTO submissions(task_id,student_id,status) SELECT ?,student_id,'PENDING' FROM enrollments WHERE course_id=?")){p.setLong(1,id);p.setLong(2,course);p.executeUpdate();}log(c,faculty,"CREATE","TASK",id,"Created "+type+": "+title);c.commit();}catch(SQLException|RuntimeException e){c.rollback();throw e;}finally{c.setAutoCommit(true);}}
    }
    public void submit(User student,long taskId) throws SQLException {requireRole(student,"STUDENT");String q="UPDATE submissions s JOIN tasks t ON t.id=s.task_id JOIN enrollments e ON e.course_id=t.course_id AND e.student_id=s.student_id SET s.status='SUBMITTED',s.submitted_at=NOW() WHERE s.task_id=? AND s.student_id=? AND s.status='PENDING'";try(Connection c=Database.connect();PreparedStatement p=c.prepareStatement(q)){p.setLong(1,taskId);p.setLong(2,student.id());if(p.executeUpdate()!=1)throw new SQLException("This task is not pending for your account.");}}
    public void evaluate(User faculty,long submissionId,double marks,String feedback) throws SQLException {requireRole(faculty,"FACULTY");if(marks<0)throw new IllegalArgumentException("Marks cannot be negative.");String q="UPDATE submissions s JOIN tasks t ON t.id=s.task_id SET s.marks=?,s.feedback=?,s.status='EVALUATED',s.evaluated_by=?,s.evaluated_at=NOW() WHERE s.id=? AND t.faculty_id=? AND ?<=t.max_marks AND s.status IN ('SUBMITTED','EVALUATED')";try(Connection c=Database.connect()){c.setAutoCommit(false);try(PreparedStatement p=c.prepareStatement(q)){p.setDouble(1,marks);p.setString(2,feedback);p.setLong(3,faculty.id());p.setLong(4,submissionId);p.setLong(5,faculty.id());p.setDouble(6,marks);if(p.executeUpdate()!=1)throw new SQLException("Submission not found, not submitted, or outside your courses; marks cannot exceed maximum.");}try(PreparedStatement p=c.prepareStatement("INSERT INTO activity_logs(user_id,action,entity_type,entity_id,description) SELECT ?, 'EVALUATE','SUBMISSION',s.id, CONCAT('Evaluated submission for ',u.name) FROM submissions s JOIN users u ON u.id=s.student_id WHERE s.id=? AND s.evaluated_by=?")){p.setLong(1,faculty.id());p.setLong(2,submissionId);p.setLong(3,faculty.id());p.executeUpdate();}c.commit();}catch(SQLException|RuntimeException e){c.rollback();throw e;}finally{c.setAutoCommit(true);}} 
    public void markAttendance(User faculty,long course,long student,LocalDate date,String status) throws SQLException {requireRole(faculty,"FACULTY");if(!status.equals("PRESENT")&&!status.equals("ABSENT"))throw new IllegalArgumentException("Attendance must be PRESENT or ABSENT.");String q="INSERT INTO attendance(course_id,student_id,class_date,attendance_status,marked_by) SELECT c.id,e.student_id,?,?,? FROM courses c JOIN enrollments e ON e.course_id=c.id WHERE c.id=? AND c.faculty_id=? AND e.student_id=? ON DUPLICATE KEY UPDATE attendance_status=VALUES(attendance_status),marked_by=VALUES(marked_by)";try(Connection c=Database.connect();PreparedStatement p=c.prepareStatement(q)){p.setDate(1,java.sql.Date.valueOf(date));p.setString(2,status);p.setLong(3,faculty.id());p.setLong(4,course);p.setLong(5,faculty.id());p.setLong(6,student);if(p.executeUpdate()!=1)throw new SQLException("Student/course is outside your assigned courses.");}}
    public static void requireRole(User u,String role){if(!u.role().equals(role)&&!u.role().equals("HOD"))throw new SecurityException("Permission denied for role "+u.role());}
    private void log(Connection c,User u,String action,String entity,long id,String desc)throws SQLException{try(PreparedStatement p=c.prepareStatement("INSERT INTO activity_logs(user_id,action,entity_type,entity_id,description) VALUES(?,?,?,?,?)")){p.setLong(1,u.id());p.setString(2,action);p.setString(3,entity);p.setLong(4,id);p.setString(5,desc);p.executeUpdate();}}
}
